R = []
R.append((7136807,
("Bagels de tomate", "Bagels tostados cubiertos con queso crema sin grasa, tomates asados y puerro en tiras.", "2", "384 g",
 ["4 tomates de rama medianos, cortados por la mitad", "1 cucharadita de aceite de canola", "1 puerro grande, en tiras", "2 bagels integrales", "60 g de queso quark sin grasa", "3 cucharaditas de cebollín fresco, picado, y 1 cucharadita para decorar", "pimienta negra recién molida"],
 ["Encienda el asador y coloque los tomates en una bandeja para hornear, con el lado cortado hacia abajo. Ase de 3 a 4 minutos, luego voltee y ase otros 3 a 4 minutos, hasta que estén ligeramente dorados.", "Mientras tanto, ponga el puerro en un recipiente apto para microondas con una cucharadita de agua, cubra con plástico adherente y cocine a máxima potencia de 2 a 3 minutos, hasta que esté suave; deje enfriar un poco y escurra el exceso de líquido.", "Corte los bagels por la mitad, tuéstelos, úntelos con el queso crema y esparza el puerro. Coloque 3 mitades de tomate sobre una mitad de bagel, espolvoree con cebollín y pimienta negra, y cubra con otra mitad de bagel. Repita con el otro bagel.", "Cubra cada uno con un poco de queso crema, otra mitad de tomate y un poco de puerro; luego decore con el cebollín restante y pimienta negra."],
 ["Pruebe agregar requesón o, para un bagel vegano, use una alternativa sin lácteos.", "Experimente con diferentes hierbas como la albahaca, o pruebe frotar el bagel tostado con un diente de ajo.", "También es delicioso con champiñones asados en lugar de tomates.", "Porciones de fruta/verdura por porción: 3"], []),
("بيغل بالطماطم", "بيغل محمّص مغطى بالجبن الكريمي الخالي من الدسم والطماطم المشوية والكراث المقطع شرائح.", "2", "384 غ",
 ["4 حبات طماطم عنقودية متوسطة، مقسومة نصفين", "1 ملعقة صغيرة زيت اللفت (الكانولا)", "1 حبة كراث كبيرة، مقطعة شرائح", "2 رغيف بيغل من القمح الكامل", "60 غ جبن كوارك خالٍ من الدسم", "3 ملعقة صغيرة ثوم معمر (شيفز) طازج، مفروم، و1 ملعقة صغيرة للتزيين", "فلفل أسود مطحون طازجًا"],
 ["شغّل الشواية وضع الطماطم على صينية خَبز بحيث يكون الجانب المقطوع لأسفل. اشوها من 3 إلى 4 دقائق، ثم اقلبها واشوها من 3 إلى 4 دقائق أخرى حتى يصبح لونها بنيًا قليلًا.", "في هذه الأثناء، ضع الكراث في وعاء صالح للميكروويف مع ملعقة صغيرة من الماء، وغطّه بغلاف بلاستيكي واطبخه على أعلى قدرة من 2 إلى 3 دقائق حتى يصبح طريًا، واتركه يبرد قليلًا ثم تخلّص من السائل الزائد.", "اقطع أرغفة البيغل إلى نصفين، وحمّصها، ثم ادهنها بالجبن الكريمي وانثر الكراث فوقها. ضع 3 أنصاف من الطماطم على نصف بيغل، ورشّ الثوم المعمر والفلفل الأسود، ثم غطّها بنصف بيغل آخر. كرّر الأمر مع الرغيف الآخر.", "ضع على كل منها قليلًا من الجبن الكريمي ونصف طماطم آخر وقليلًا من الكراث، ثم زيّنها بالثوم المعمر المتبقي والفلفل الأسود."],
 ["جرّب إضافة جبن القريش، أو استخدم بديلًا غير لبني للحصول على بيغل نباتي.", "جرّب أعشابًا مختلفة مثل الريحان، أو جرّب فرك البيغل المحمّص بفص ثوم.", "لذيذ أيضًا مع الفطر المشوي بدلًا من الطماطم.", "حصص الفاكهة/الخضار في الحصة الواحدة: 3"], [])))
R.append((7137182,
("Tempura de camarones y verduras", "Ligera y crujiente, es ideal para servir como acompañamiento de bebidas en una fiesta.", "6", "138 g",
 ["1 yema de huevo", "125 g de harina de trigo todo uso, tamizada", "12 camarones tigre crudos, pelados", "450 g de verduras mixtas", "aceite, para freír"],
 ["Bata la yema de huevo con 200 ml de agua helada. Agregue la harina y mezcle sin trabajar demasiado.", "No se trata de hacer una masa lisa; la mezcla debe quedar bastante grumosa, ya que eso le da su ligereza al freírla.", "Caliente el aceite en una olla grande hasta que un trozo de pan se dore en 30 segundos.", "Sumerja los camarones y las verduras en la masa y fría por tandas. Voltee con frecuencia para que se cocinen de manera uniforme, hasta que tengan un color dorado claro, unos 2 a 3 minutos por tanda.", "Escurra sobre papel de cocina y sirva."],
 ["Para la tempura necesita verduras de cocción rápida. Los chícharos dulces, los chícharos chinos, los ejotes, el apio y las cebollitas de cambray también son ideales.", "Para una salsa saludable para mojar, simplemente licúe 2 puñados de hierbas frescas mixtas (por ejemplo, perejil, cilantro, menta, albahaca) con un diente de ajo fresco, el jugo y la ralladura de 1 limón y 2 cucharadas de aceite de oliva.", "Porciones de fruta/verdura por porción: 1"], []),
("تمبورا الجمبري والخضار", "خفيفة ومقرمشة، وهي رائعة كمقبّلات تُقدَّم مع المشروبات في الحفلات.", "6", "138 غ",
 ["1 صفار بيضة", "125 غ دقيق عادي، منخول", "12 جمبري نمري نيئ، مقشّر", "450 غ خضار مشكّلة", "زيت، للقلي العميق"],
 ["اخفق صفار البيضة مع 200 مل من الماء المثلج. أضف الدقيق وامزجه بشكل تقريبي.", "لا تحضّر عجينة ناعمة، بل يجب أن يبقى الخليط متكتلًا إلى حد ما، لأن ذلك يمنحه الخفة عند القلي.", "سخّن الزيت في قدر كبير حتى تتحمّر قطعة خبز خلال 30 ثانية.", "اغمس الجمبري والخضار في الخليط واقلها على دفعات. قلّبها باستمرار لضمان نضجها بالتساوي حتى يصبح لونها ذهبيًا فاتحًا، نحو 2 إلى 3 دقائق لكل دفعة.", "صفّها على ورق المطبخ وقدّمها."],
 ["تحتاج إلى خضار سريعة النضج لتحضير التمبورا. ويُعدّ البازلاء السكرية والفاصولياء الخضراء والكرفس والبصل الأخضر مثالية أيضًا.", "للحصول على صلصة صحية للغمس، ما عليك سوى خلط حفنتين من الأعشاب الطازجة المشكّلة (مثل البقدونس والكزبرة والنعناع والريحان) مع فص ثوم طازج وعصير وقشر ليمونة واحدة وملعقتين كبيرتين من زيت الزيتون.", "حصص الفاكهة/الخضار في الحصة الواحدة: 1"], [])))
R.append((7138695,
("Risotto de mariscos", "Camarones, calamares y mejillones se combinan con pimiento y calabacita para crear un sabroso risotto de mariscos.", "4", "462 g",
 ["1 cucharadita de aceite de canola", "1 cebolla, picada finamente", "1 cubito de caldo de pescado bajo en sal disuelto en 900 ml de agua", "1 pimiento rojo, picado finamente", "1 calabacita, picada finamente", "1 diente de ajo, machacado", "1 buena pizca de pimienta blanca", "15 g de perejil, picado finamente, y 1 cucharada para servir", "150 g de arroz Arborio", "1 bolsa de 350 g de mariscos mixtos congelados, descongelados (mejillones 37 %, calamares 25 %, camarones 25 %)", "1 cucharada de yogur griego 0 % grasa", "1 pizca de perejil y pimienta negra para servir"],
 ["Agregue el aceite a una olla y cocine la cebolla 5 minutos. En otra olla, caliente el caldo y manténgalo a fuego lento.", "Agregue a la cebolla el pimiento rojo, la calabacita, el ajo, la pimienta blanca y la mitad del perejil. Revuelva 1 minuto antes de agregar el arroz. Revuelva 2 minutos, luego agregue 2 cucharones de caldo, lo suficiente para apenas cubrir el arroz, y revuelva.", "Agregue el caldo caliente poco a poco, de modo que el arroz quede apenas cubierto, revolviendo con frecuencia. El risotto debe hervir muy suavemente.", "Después de 20 minutos, agregue el caldo restante y los mariscos, y revuelva otros 3 a 4 minutos. Pruebe el arroz para asegurarse de que esté al dente (ligeramente firme) y compruebe que todos los mariscos estén bien cocidos.", "Por último, incorpore enérgicamente el perejil restante, guardando un poco para servir. Agregue el yogur, revuelva, tape y deje reposar 2 minutos antes de servir con una pizca de perejil y una buena molida de pimienta negra."],
 ["Mantenga el caldo a fuego lento en una olla aparte para que esté muy caliente al agregarlo al arroz y así el arroz se cocine de manera uniforme. Agréguelo poco a poco; si se acaba, simplemente agregue un poco de agua hirviendo.", "Revolver con frecuencia con una cuchara de madera hace que el arroz libere su almidón y logre una textura cremosa.", "Instrucciones para congelar: Se puede congelar una vez cocinado. Luego descongele en el refrigerador y recaliente hasta que esté muy caliente por completo. Deseche las sobras y no las vuelva a calentar ni a congelar.", "Porciones de fruta/verdura por porción: 1"], []),
("ريزوتو المأكولات البحرية", "يجتمع الجمبري والحبار وبلح البحر مع الفلفل الرومي والكوسا لتحضير ريزوتو لذيذ بالمأكولات البحرية.", "4", "462 غ",
 ["1 ملعقة صغيرة زيت اللفت (الكانولا)", "1 حبة بصل، مفرومة ناعمًا", "1 مكعب مرق سمك قليل الملح مذاب في 900 مل ماء", "1 حبة فلفل رومي أحمر، مفرومة ناعمًا", "1 حبة كوسا، مفرومة ناعمًا", "1 فص ثوم، مهروس", "رشة كبيرة من الفلفل الأبيض", "15 غ بقدونس، مفروم ناعمًا، و1 ملعقة كبيرة للتقديم", "150 غ أرز أربوريو", "1 كيس 350 غ مأكولات بحرية مشكّلة مجمدة، مذابة (بلح البحر 37%، حبار 25%، جمبري 25%)", "1 ملعقة كبيرة زبادي يوناني خالٍ من الدسم (0%)", "رشة بقدونس وفلفل أسود للتقديم"],
 ["ضع الزيت في قدر واطبخ البصل 5 دقائق. في قدر منفصل، سخّن المرق واتركه على نار هادئة.", "أضف الفلفل الرومي الأحمر والكوسا والثوم والفلفل الأبيض ونصف البقدونس إلى البصل. حرّك دقيقة واحدة قبل إضافة الأرز. حرّك دقيقتين، ثم أضف مغرفتين من المرق، بما يكفي لتغطية الأرز بالكاد، وحرّك.", "أضف المرق الساخن شيئًا فشيئًا بحيث يكون الأرز مغطى بالكاد، مع التحريك باستمرار. يجب أن يغلي الريزوتو بهدوء شديد.", "بعد 20 دقيقة، أضف أي مرق متبقٍّ والمأكولات البحرية، ثم حرّك 3 إلى 4 دقائق أخرى. تذوّق الأرز للتأكد من أنه مطهو «آل دنتي» (متماسك قليلًا) وتأكد من نضج جميع المأكولات البحرية تمامًا.", "وأخيرًا، حرّك بقوة البقدونس المتبقي مع الاحتفاظ بقليل منه للتقديم. أضف الزبادي وحرّك، ثم غطِّ واتركه يرتاح دقيقتين، قبل التقديم مع رشة بقدونس ورشة كبيرة من الفلفل الأسود."],
 ["أبقِ المرق على نار هادئة في قدر منفصل لكي يكون ساخنًا جدًا عند إضافته إلى الأرز، وهذا يضمن نضج الأرز بشكل متجانس. أضفه شيئًا فشيئًا، وإن نفد فأضف قليلًا من الماء المغلي.", "التحريك المستمر بملعقة خشبية يجعل الأرز يطلق نشاه ليمنح الريزوتو قوامًا كريميًا.", "تعليمات التجميد: يمكن تجميده بعد الطهي. ثم أذبه في الثلاجة وأعد تسخينه حتى يصبح ساخنًا تمامًا من الداخل. تخلّص من أي بقايا ولا تعد تسخينها أو تجميدها.", "حصص الفاكهة/الخضار في الحصة الواحدة: 1"], [])))
R.append((7142366,
("Frijoles mixtos estofados", "Un excelente platillo vegetariano con un sabor profundo y sabroso.", "4", "418 g",
 ["2 cebollas moradas, picadas en cubitos finos", "2 dientes de ajo, machacados", "2 tallos de apio, picados", "115 g de lentejas rojas, enjuagadas", "1 cucharada de tomillo fresco picado", "300 ml de agua y 1 cucharada de vinagre", "1 lata de 400 g de tomates picados", "1 lata de 400 g de frijoles rojos en agua, escurridos y enjuagados", "1 lata de 400 g de frijoles cannellini en agua, escurridos y enjuagados", "1 a 2 cucharaditas de caldo de verduras en polvo", "pimienta negra"],
 ["Caliente una sartén grande antiadherente, agregue las cebollas y el ajo y saltee sin aceite hasta que se ablanden. Agregue el apio, las lentejas y el tomillo.", "Vierta el agua mezclada con el vinagre, los tomates y los frijoles; luego incorpore el caldo en polvo.", "Deje que hierva y luego reduzca a fuego lento.", "Cocine a fuego lento 20 minutos, hasta que las lentejas estén suaves, agregando un poco de agua si es necesario. Sazone al gusto."],
 ["Use caldo de verduras en polvo sin gluten para que esta receta sea libre de gluten.", "También puede preparar este platillo con 2 latas de frijoles mixtos, o con una lata de frijoles y una lata de lentejas.", "Apto para congelar una vez cocinado. Descongele en el refrigerador y recaliente hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por porción: 4"], []),
("فاصولياء مشكّلة مطهوة ببطء", "طبق نباتي رائع بنكهة عميقة ولذيذة.", "4", "418 غ",
 ["2 حبة بصل أحمر، مفرومة مكعبات صغيرة", "2 فص ثوم، مهروسة", "2 ساق كرفس، مفرومة", "115 غ عدس أحمر، مشطوف", "1 ملعقة كبيرة زعتر طازج مفروم", "300 مل ماء وملعقة كبيرة خل", "1 علبة 400 غ طماطم مقطعة", "1 علبة 400 غ فاصولياء حمراء في الماء، مصفّاة ومشطوفة", "1 علبة 400 غ فاصولياء كانليني في الماء، مصفّاة ومشطوفة", "1-2 ملعقة صغيرة مسحوق مرق الخضار", "فلفل أسود"],
 ["سخّن مقلاة كبيرة غير لاصقة، وأضف البصل والثوم وقلّبهما دون زيت حتى يذبلا. أضف الكرفس والعدس والزعتر.", "اسكب الماء الممزوج بالخل، ثم أضف الطماطم والفاصولياء، وبعد ذلك أضف مسحوق المرق وحرّك.", "اتركها حتى تغلي، ثم اخفض الحرارة لتغلي برفق.", "اتركها على نار هادئة 20 دقيقة حتى يلين العدس، مع إضافة قليل من الماء عند الحاجة. تبّلها حسب الذوق."],
 ["استخدم مسحوق مرق خضار خاليًا من الغلوتين لجعل هذه الوصفة خالية من الغلوتين.", "يمكنك أيضًا تحضير هذا الطبق بعلبتين من الفاصولياء المشكّلة، أو بعلبة فاصولياء وعلبة عدس.", "يمكن تجميده بعد الطهي. أذبه في الثلاجة وأعد تسخينه حتى يصبح ساخنًا تمامًا من الداخل.", "حصص الفاكهة/الخضار في الحصة الواحدة: 4"], [])))
R.append((7145749,
("Saag aloo (espinacas con papas)", "Una guarnición sabrosa o una comida ligera: un clásico en la mayoría de los menús de la India.", "6", "259 g",
 ["1 cucharada de aceite de oliva", "1 cebolla grande, picada finamente", "4 dientes de ajo, picados finamente", "1 a 3 chiles verdes (según qué tan picante lo prefiera), picados finamente", "1 cucharada de jengibre fresco picado", "1 cucharadita de cúrcuma", "750 g de papas, peladas y cortadas en trozos pequeños", "de ½ a 1½ cucharaditas de chile rojo en polvo", "750 g de hojas de espinaca, lavadas y picadas"],
 ["Caliente el aceite en una sartén antiadherente, agregue la cebolla, el ajo, el chile y el jengibre y cocine de 2 a 3 minutos, hasta que se ablanden.", "Incorpore la cúrcuma y cocine 5 minutos. Agregue las papas y el chile rojo en polvo, revuelva, tape y cocine de 15 a 20 minutos a fuego medio, revolviendo con frecuencia.", "Incorpore las espinacas, tape y cocine de 25 a 30 minutos, hasta que las papas estén suaves y la mezcla esté bastante seca."],
 ["Este platillo funciona bien con espinacas congeladas. Solo descongele y agregue cuando las papas estén casi cocidas.", "Si no tiene chiles frescos, jengibre o las especias, puede agregar 1 cucharada de pasta de curry, suave o picante, la que prefiera.", "Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele por completo y recaliente hasta que esté muy caliente.", "Porciones de fruta/verdura por porción: 1"], []),
("ساغ ألو (سبانخ وبطاطس)", "طبق جانبي لذيذ أو وجبة خفيفة، وهو حاضر دائمًا في معظم قوائم المطاعم الهندية.", "6", "259 غ",
 ["1 ملعقة كبيرة زيت زيتون", "1 حبة بصل كبيرة، مفرومة ناعمًا", "4 فصوص ثوم، مفرومة ناعمًا", "1-3 حبات فلفل أخضر حار (حسب درجة الحرارة التي تفضلها)، مفرومة ناعمًا", "1 ملعقة كبيرة زنجبيل طازج مفروم", "1 ملعقة صغيرة كركم", "750 غ بطاطس، مقشّرة ومقطعة قطعًا صغيرة", "نصف إلى 1½ ملعقة صغيرة مسحوق فلفل أحمر حار", "750 غ أوراق سبانخ، مغسولة ومفرومة"],
 ["سخّن الزيت في مقلاة غير لاصقة، وأضف البصل والثوم والفلفل الحار والزنجبيل واطبخها من 2 إلى 3 دقائق حتى تذبل.", "أضف الكركم وحرّك واطبخ 5 دقائق. أضف البطاطس ومسحوق الفلفل الأحمر الحار وحرّك وغطِّ واطبخ من 15 إلى 20 دقيقة على نار متوسطة مع التحريك باستمرار.", "أضف السبانخ وحرّك، وغطِّ واطبخ من 25 إلى 30 دقيقة حتى تنضج البطاطس ويصبح الخليط جافًا إلى حد كبير."],
 ["يناسب هذا الطبق السبانخ المجمدة. أذبها فقط وأضفها عندما تكاد البطاطس تنضج.", "إذا لم يكن لديك فلفل حار طازج أو زنجبيل أو التوابل، فيمكنك إضافة ملعقة كبيرة من معجون الكاري، سواء الخفيف أو الحار حسب تفضيلك.", "تعليمات التجميد: يمكن تجميده بعد الطهي. أذبه تمامًا وأعد تسخينه حتى يصبح ساخنًا جدًا.", "حصص الفاكهة/الخضار في الحصة الواحدة: 1"], [])))
R.append((7146637,
("Relleno de castañas y albaricoque", "Un relleno bajo en grasa que puede usarse para rellenar pavo y pollo, o verduras como berenjena, pimientos o calabaza.", "10", "128 g",
 ["1 cucharada de aceite de girasol", "4 a 5 cebollas (450 g), picadas", "2 dientes de ajo, machacados", "6 rebanadas de pan integral (240 g), desmenuzadas en trozos grandes", "1 cucharadita colmada de tomillo seco (o 2 cucharaditas de tomillo fresco)", "1 buena pizca de pimienta", "100 g de orejones de albaricoque listos para comer, algunos partidos por la mitad y otros picados en trozos grandes", "1 paquete de 200 g de castañas envasadas al vacío, algunas partidas por la mitad y otras enteras", "2 cucharadas de perejil recién picado"],
 ["Caliente el aceite en una sartén, agregue la cebolla y fría 5 minutos, hasta que se ablande y empiece a dorarse; luego agregue el ajo y cocine 1 minuto más.", "Mientras tanto, ponga el pan, el tomillo, la pimienta y 500 ml de agua hirviendo en un tazón, deje reposar un par de minutos y luego revuelva con un tenedor para deshacer todo el pan hasta obtener una papilla espesa.", "Agregue las cebollas y el ajo a la mezcla de pan junto con los albaricoques, las castañas y el perejil, y mezcle bien.", "Pase a un molde para horno ligeramente engrasado y hornee de 25 a 35 minutos."],
 ["Pruebe con otras hierbas en lugar de tomillo. La salvia o el estragón quedan muy bien. También puede usar otras frutas secas, como ciruelas pasas, arándanos rojos o pasas, en lugar de albaricoques.", "Es ideal como guarnición de platillos vegetarianos y veganos, o con carnes como cerdo y faisán.", "Porciones de fruta/verdura por porción: 0"], []),
("حشوة الكستناء والمشمش", "حشوة قليلة الدسم يمكن استخدامها لحشو الديك الرومي والدجاج، أو لحشو الخضار مثل الباذنجان أو الفلفل أو القرع.", "10", "128 غ",
 ["1 ملعقة كبيرة زيت دوار الشمس", "4-5 حبات بصل (450 غ)، مفرومة", "2 فص ثوم، مهروسة", "6 شرائح خبز القمح الكامل (240 غ)، ممزقة خشنًا", "1 ملعقة صغيرة مكوّمة زعتر مجفف (أو 2 ملعقة صغيرة زعتر طازج)", "رشة كبيرة من الفلفل", "100 غ مشمش مجفف جاهز للأكل، بعضه مقسوم نصفين وبعضه مفروم خشنًا", "1 عبوة 200 غ كستناء معبأة بالتفريغ، بعضها مقسوم نصفين وبعضها كامل", "2 ملعقة كبيرة بقدونس طازج مفروم"],
 ["سخّن الزيت في مقلاة، وأضف البصل وقلّبه 5 دقائق حتى يذبل ويبدأ لونه بالاحمرار، ثم أضف الثوم واطبخ دقيقة أخرى.", "في هذه الأثناء، ضع الخبز والزعتر والفلفل و500 مل من الماء المغلي في وعاء، واتركه دقيقتين ثم حرّكه بالشوكة لتفتيت كل الخبز إلى عصيدة سميكة.", "أضف البصل والثوم إلى خليط الخبز مع المشمش والكستناء والبقدونس وامزج جيدًا.", "ضعه في طبق مقاوم للحرارة مدهون بقليل من الزيت واخبزه من 25 إلى 35 دقيقة."],
 ["جرّب إضافة أعشاب أخرى بدلًا من الزعتر. فالميرمية أو الطرخون يعطيان نتيجة جيدة. ويمكنك أيضًا استخدام فواكه مجففة أخرى مثل البرقوق أو التوت البري أو الزبيب بدلًا من المشمش.", "مثالية كطبق جانبي مع الأطباق النباتية والنباتية الصرفة أو مع اللحوم مثل لحم الخنزير والدرّاج.", "حصص الفاكهة/الخضار في الحصة الواحدة: 0"], [])))
